using System;using System.IO;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace PZ3D {static class JournalPrivacyTests {
 public static int Main(){try{Run();return 0;}catch(Exception x){Console.WriteLine(x);return 1;}}
 static void Nested(){string payload=new JavaScriptSerializer().Serialize(new{message="{\"userPassword\":\"fixture password space\",\"token\":\"fixture ticket space\"}"});string result=LauncherJournal.Sanitize(payload);if(result.Contains("fixture password space")||result.Contains("fixture ticket space"))throw new Exception("FAIL: nested escaped JSON leaked quoted secrets with whitespace");string quoted=new JavaScriptSerializer().Serialize(new{userPassword="fixture prefix \" fixture-tail-secret"});if(LauncherJournal.Sanitize(quoted).Contains("fixture-tail-secret"))throw new Exception("FAIL: quoted credential tail survived sanitization");}
 public static void Run(){Nested();string json="{\"userPassword\":\"secret-example\",\"serverPassword\":\"another-secret\",\"token\":\"steam-ticket\",\"message\":\"ordinary\"}";string cleaned=LauncherJournal.Sanitize(json);if(cleaned.Contains("secret-example")||cleaned.Contains("another-secret")||cleaned.Contains("steam-ticket"))throw new Exception("FAIL: quoted JSON credentials leaked to diagnostic messages");string data=Path.Combine(LauncherTestPaths.Root,"journal-volume-"+Guid.NewGuid().ToString("N"));var journal=new LauncherJournal(data);for(int task=0;task<8;task++){journal.Begin("maintenance","Large synthetic task");for(int step=0;step<40;step++)journal.Update(step,new string('中',1000));journal.Finish("failed","Synthetic failure");}string record=Path.Combine(data,"diagnostics","tasks.json");if(new FileInfo(record).Length>1572864)throw new Exception("FAIL: durable tasks don't rotate to bounded capacity");if(!new JavaScriptSerializer{MaxJsonLength=2097152}.Serialize(journal.Snapshot()).Contains("failed"))throw new Exception("FAIL: bounded history lost latest task status");Console.WriteLine("PASS: JSON credential redaction and bounded durable task rotation");}
}}
